import{_ as a}from"./plugin-vue_export-helper-c27b6911.js";import{o as n,c as s,e}from"./app-09e0be14.js";const t={},p=e(`<h1 id="imagemagick-强大的命令行图像处理套件" tabindex="-1"><a class="header-anchor" href="#imagemagick-强大的命令行图像处理套件" aria-hidden="true">#</a> imagemagick（强大的命令行图像处理套件）</h1><blockquote><p>Homebrew 版本 7.1.2-9 ｜ 主页：见官方文档 ｜ 安装：<code>brew install imagemagick</code></p></blockquote><h2 id="一、它是什么" tabindex="-1"><a class="header-anchor" href="#一、它是什么" aria-hidden="true">#</a> 一、它是什么</h2><p>ImageMagick 是一套功能极其强大的<strong>命令行图像处理套件</strong>，通过 <code>convert</code>、<code>magick</code>、<code>identify</code>、<code>montage</code> 等子命令对图像进行创建、转换、合成、裁剪、缩放、加水印、加边框、分析等操作，无需打开任何 GUI 即可批量处理海量图片。它解决的核心问题是&quot;用一行命令搞定图像处理的重复劳动&quot;，典型应用场景包括：批量缩放/压缩网站图片、把多种格式统一转成 JPEG/PNG/WebP、给图片加水印和缩略图、拼接对比图、读取图片元数据（EXIF/尺寸/色彩空间）等。</p><blockquote><p>注：ImageMagick 7 起，传统 <code>convert</code> 命令已迁移到统一的 <code>magick</code> 命令（<code>magick convert</code> 别名保留兼容）。本文示例以 7.x 的 <code>magick</code> 为主，同时注明旧版 <code>convert</code> 写法。</p></blockquote><h2 id="二、安装与升级" tabindex="-1"><a class="header-anchor" href="#二、安装与升级" aria-hidden="true">#</a> 二、安装与升级</h2><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 安装</span>
brew <span class="token function">install</span> imagemagick

<span class="token comment"># 升级</span>
brew upgrade imagemagick

<span class="token comment"># 卸载</span>
brew uninstall imagemagick

<span class="token comment"># 验证安装成功（查看版本，应显示 7.1.2-9 之类）</span>
magick <span class="token parameter variable">--version</span>

<span class="token comment"># 查看已启用的组件（编码器、委托工具等）</span>
magick <span class="token parameter variable">-version</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>安装后 <code>magick</code>、<code>convert</code>、<code>identify</code>、<code>montage</code>、<code>mogrify</code>、<code>compare</code> 等命令即进入 PATH，直接可全局调用。ImageMagick 默认编译了大量格式支持（JPEG、PNG、GIF、TIFF、WebP、HEIC 等），无需额外安装编解码器即可覆盖绝大多数场景。</p><blockquote><p>可选依赖：如需更强的编解码能力（HEIC、RAW、PDF 页级转换等），可安装 <code>brew install heif libheif libraw ghostscript</code> 等。查看当前缺失的 delegate 可用 <code>magick -list delegate</code>，再针对性安装。</p></blockquote><h2 id="三、常用命令速查" tabindex="-1"><a class="header-anchor" href="#三、常用命令速查" aria-hidden="true">#</a> 三、常用命令速查</h2><table><thead><tr><th>命令</th><th>参数说明</th><th>示例</th></tr></thead><tbody><tr><td><code>magick input.png -resize 50% out.png</code></td><td>缩放图片（支持百分比或像素尺寸）</td><td><code>magick a.png -resize 800x600 b.png</code></td></tr><tr><td><code>magick input.png -quality 80 out.jpg</code></td><td>设置 JPEG 压缩质量（0-100）</td><td><code>magick a.png -quality 80 a.jpg</code></td></tr><tr><td><code>magick input.png -crop 300x300+50+50 out.png</code></td><td>裁剪：宽x高+左偏移+上偏移</td><td><code>magick a.png -crop 100x100+0+0 b.png</code></td></tr><tr><td><code>magick input.png -rotate 90 out.png</code></td><td>旋转角度（支持顺时针正数/逆时负数）</td><td><code>magick a.png -rotate -90 b.png</code></td></tr><tr><td><code>magick input.png -format &quot;%wx%h&quot; info:</code></td><td>读取图片宽高（identify 的替代）</td><td><code>magick a.png -format &quot;%wx%h&quot; info:</code></td></tr><tr><td><code>identify input.png</code></td><td>查看图片信息（尺寸、类型、色彩）</td><td><code>identify photo.jpg</code></td></tr><tr><td><code>magick *.png -append out.png</code></td><td>垂直拼接多图；<code>+append</code> 为水平拼接</td><td><code>magick 1.png 2.png +append row.png</code></td></tr><tr><td><code>magick input.png -gravity center -pointsize 40 -annotate +0+0 &quot;文本&quot; out.png</code></td><td>在图上居中叠加文字</td><td><code>magick a.png -gravity south -annotate +0+10 &quot;© 2024&quot; b.png</code></td></tr><tr><td><code>mogrify -resize 50% *.png</code></td><td>原地批量处理（直接覆盖原文件）</td><td><code>mogrify -resize 50% -path out/ *.jpg</code></td></tr><tr><td><code>magick -size 800x600 gradient:blue-red out.png</code></td><td>生成渐变等合成图像</td><td><code>magick -size 100x100 plasma:fractal noise.png</code></td></tr></tbody></table><h2 id="四、实际示例" tabindex="-1"><a class="header-anchor" href="#四、实际示例" aria-hidden="true">#</a> 四、实际示例</h2><h3 id="示例-1-批量缩放压缩一组照片" tabindex="-1"><a class="header-anchor" href="#示例-1-批量缩放压缩一组照片" aria-hidden="true">#</a> 示例 1：批量缩放压缩一组照片</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：创建测试图片（用 ImageMagick 生成几张渐变图）</span>
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> ~/imgtest <span class="token operator">&amp;&amp;</span> <span class="token builtin class-name">cd</span> ~/imgtest
magick <span class="token parameter variable">-size</span> 2000x1500 gradient:skyblue-navy p1.png
magick <span class="token parameter variable">-size</span> 1800x1200 plasma:fractal p2.png

<span class="token comment"># 批量缩放到宽 1200（保持比例），输出到 out/ 目录并转成 JPEG</span>
<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> out
magick p1.png <span class="token parameter variable">-resize</span> 1200x out/p1.jpg
magick p2.png <span class="token parameter variable">-resize</span> 1200x out/p2.jpg

<span class="token comment"># 查看结果尺寸与文件大小</span>
identify out/p1.jpg out/p2.jpg
<span class="token function">ls</span> <span class="token parameter variable">-lh</span> out/
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出形如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>out/p1.jpg PNG 1200x900 1200x900+0+0 8-bit sRGB 96KB 0.000u 0:00.000
out/p2.jpg PNG 1200x750 1200x750+0+0 8-bit sRGB 61KB 0.000u 0:00.000
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-2-给图片加水印并导出-webp" tabindex="-1"><a class="header-anchor" href="#示例-2-给图片加水印并导出-webp" aria-hidden="true">#</a> 示例 2：给图片加水印并导出 WebP</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：生成一张原图和一张半透明水印</span>
<span class="token builtin class-name">cd</span> ~/imgtest
magick <span class="token parameter variable">-size</span> 1600x1000 gradient:purple-orange photo.png
magick <span class="token parameter variable">-size</span> 400x100 xc:none <span class="token parameter variable">-fill</span> <span class="token string">&quot;rgba(255,255,255,0.6)&quot;</span> <span class="token punctuation">\\</span>
  <span class="token parameter variable">-gravity</span> center <span class="token parameter variable">-pointsize</span> <span class="token number">48</span> <span class="token parameter variable">-annotate</span> +0+0 <span class="token string">&quot;BeauXbot&quot;</span> watermark.png

<span class="token comment"># 把水印合成到原图右下角，导出为质量 85 的 WebP</span>
magick photo.png watermark.png <span class="token parameter variable">-gravity</span> southeast <span class="token parameter variable">-geometry</span> +20+20 <span class="token punctuation">\\</span>
  <span class="token parameter variable">-composite</span> <span class="token parameter variable">-quality</span> <span class="token number">85</span> photo.webp

<span class="token comment"># 校验输出</span>
identify photo.webp
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-3-读取并分析图片信息" tabindex="-1"><a class="header-anchor" href="#示例-3-读取并分析图片信息" aria-hidden="true">#</a> 示例 3：读取并分析图片信息</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：随便找一张已有图片</span>
<span class="token builtin class-name">cd</span> ~/imgtest

<span class="token comment"># 完整信息</span>
identify <span class="token parameter variable">-verbose</span> photo.png

<span class="token comment"># 仅提取关键字段</span>
identify <span class="token parameter variable">-format</span> <span class="token string">&quot;尺寸: %wx%h<span class="token entity" title="\\n">\\n</span>类型: %m<span class="token entity" title="\\n">\\n</span>色彩: %[colorspace]<span class="token entity" title="\\n">\\n</span>&quot;</span> photo.png

<span class="token comment"># 用 magick 的 info: 读取尺寸（脚本友好，可赋值给变量）</span>
<span class="token assign-left variable">width</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>magick photo.png <span class="token parameter variable">-format</span> <span class="token string">&quot;%w&quot;</span> info:<span class="token variable">)</span></span>
<span class="token assign-left variable">height</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>magick photo.png <span class="token parameter variable">-format</span> <span class="token string">&quot;%h&quot;</span> info:<span class="token variable">)</span></span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;宽=<span class="token variable">$width</span> 高=<span class="token variable">$height</span>&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>输出形如：</p><div class="language-text line-numbers-mode" data-ext="text"><pre class="language-text"><code>尺寸: 1600x1000
类型: PNG
色彩: sRGB
宽=1600 高=1000
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="示例-4-拼接对比图-before-after" tabindex="-1"><a class="header-anchor" href="#示例-4-拼接对比图-before-after" aria-hidden="true">#</a> 示例 4：拼接对比图（before/after）</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 准备：一张原图、一张模糊处理后的图</span>
<span class="token builtin class-name">cd</span> ~/imgtest
magick photo.png blur_photo.png

<span class="token comment"># 水平并排拼接成对比图</span>
magick photo.png blur_photo.png +append before_after.png

<span class="token comment"># 查看拼接结果</span>
identify before_after.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h2 id="五、进阶技巧与配置" tabindex="-1"><a class="header-anchor" href="#五、进阶技巧与配置" aria-hidden="true">#</a> 五、进阶技巧与配置</h2><h3 id="_5-1-用-path-避免覆盖原文件" tabindex="-1"><a class="header-anchor" href="#_5-1-用-path-避免覆盖原文件" aria-hidden="true">#</a> 5.1 用 <code>-path</code> 避免覆盖原文件</h3><p><code>mogrify</code> 默认原地覆盖。批量处理时用 <code>-path 输出目录</code> 把结果写到新目录，避免误毁原图：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>mogrify <span class="token parameter variable">-resize</span> <span class="token number">50</span>% <span class="token parameter variable">-quality</span> <span class="token number">80</span> <span class="token parameter variable">-path</span> ./thumb/ *.jpg
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><blockquote><p>注意：<code>mogrify -path</code> 输出的<strong>文件名与输入保持一致</strong>。若需改名，用 <code>-set filename:out &quot;%t&quot;</code> 等 <code>%[filename]</code> 转义，或配合 <code>find/xargs</code> 逐张处理。</p></blockquote><h3 id="_5-2-并发加速与资源限制" tabindex="-1"><a class="header-anchor" href="#_5-2-并发加速与资源限制" aria-hidden="true">#</a> 5.2 并发加速与资源限制</h3><p>多核机器上 ImageMagick 默认尽量多线程，但海量小图时单进程反而更快。可按需控制：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 环境变量控制全局线程数</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">MAGICK_THREAD_LIMIT</span><span class="token operator">=</span><span class="token number">4</span>

<span class="token comment"># 单条命令内临时限制（-limit 语法）</span>
magick <span class="token parameter variable">-limit</span> thread <span class="token number">2</span> <span class="token parameter variable">-resize</span> <span class="token number">50</span>% big.png out.png

<span class="token comment"># 用 xargs 的 -P 做进程级并发（每个进程 1 线程，互不干扰）</span>
<span class="token function">find</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.jpg&#39;</span> <span class="token parameter variable">-print0</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-0</span> <span class="token parameter variable">-P</span> <span class="token number">4</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token punctuation">\\</span>
  mogrify <span class="token parameter variable">-resize</span> 800x <span class="token parameter variable">-path</span> ./out/ <span class="token punctuation">{</span><span class="token punctuation">}</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>原则：大图、多核重活优先 <code>-limit thread</code> 单进程多线程；海量小文件优先 <code>xargs -P</code> 多进程。</p><h3 id="_5-3-格式转换工作流-jpeg-png-webp-avif" tabindex="-1"><a class="header-anchor" href="#_5-3-格式转换工作流-jpeg-png-webp-avif" aria-hidden="true">#</a> 5.3 格式转换工作流（JPEG / PNG / WebP / AVIF）</h3><p>ImageMagick 是天然的&quot;格式枢纽&quot;，靠<strong>输出扩展名</strong>决定目标格式：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 统一转成质量 80 的 WebP（体积约为 JPEG 的 60-70%）</span>
magick photo.png <span class="token parameter variable">-strip</span> <span class="token parameter variable">-quality</span> <span class="token number">80</span> photo.webp

<span class="token comment"># 转成 AVIF（新一代，体积更小，兼容性逐年提升）</span>
magick photo.png <span class="token parameter variable">-strip</span> <span class="token parameter variable">-quality</span> <span class="token number">60</span> photo.avif

<span class="token comment"># 保留透明通道转 PNG，去掉背景转 JPEG（JPEG 不支持透明，需先填白底）</span>
magick photo.png <span class="token parameter variable">-background</span> white <span class="token parameter variable">-flatten</span> photo.jpg

<span class="token comment"># 批量：png -&gt; webp，保留原文件名</span>
<span class="token function">find</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.png&#39;</span> <span class="token parameter variable">-print0</span> <span class="token operator">|</span> <span class="token keyword">while</span> <span class="token assign-left variable"><span class="token environment constant">IFS</span></span><span class="token operator">=</span> <span class="token builtin class-name">read</span> <span class="token parameter variable">-r</span> <span class="token parameter variable">-d</span> <span class="token string">&#39;&#39;</span> f<span class="token punctuation">;</span> <span class="token keyword">do</span>
  magick <span class="token string">&quot;<span class="token variable">$f</span>&quot;</span> <span class="token parameter variable">-strip</span> <span class="token parameter variable">-resize</span> 1200x <span class="token parameter variable">-quality</span> <span class="token number">80</span> <span class="token string">&quot;<span class="token variable">\${f<span class="token operator">%</span>.png}</span>.webp&quot;</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>常用工作流建议：</p><ul><li><strong>网站首图</strong>：WebP <code>-quality 80</code> + <code>-strip</code>（去 EXIF/ICC 等元数据，进一步减小体积）。</li><li><strong>需兼容老环境</strong>：JPEG <code>-quality 82</code> + <code>-interlace Plane</code>（渐进式，Web 友好）。</li><li><strong>图标/贴纸</strong>：PNG，可加 <code>-strip</code> 去冗余元数据。</li><li><strong>动画</strong>：GIF 保留多帧，<code>-coalesce</code> 统一各帧画布；转 WebP 动画用 <code>-loop 0</code>。</li></ul><h3 id="_5-4-批量处理-排序输出" tabindex="-1"><a class="header-anchor" href="#_5-4-批量处理-排序输出" aria-hidden="true">#</a> 5.4 批量处理 + 排序输出</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 当前目录所有 JPEG 缩放到 800 宽，按文件名排序，输出到 out/</span>
<span class="token function">find</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.jpg&#39;</span> <span class="token parameter variable">-print0</span> <span class="token operator">|</span> <span class="token function">sort</span> <span class="token parameter variable">-z</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-0</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token punctuation">\\</span>
  magick <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token parameter variable">-resize</span> 800x <span class="token parameter variable">-path</span> ./out/ <span class="token punctuation">{</span><span class="token punctuation">}</span>.thumb.jpg
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_5-5-批量缩放不超尺寸-fit-within-与裁剪填充-cover" tabindex="-1"><a class="header-anchor" href="#_5-5-批量缩放不超尺寸-fit-within-与裁剪填充-cover" aria-hidden="true">#</a> 5.5 批量缩放不超尺寸（fit within）与裁剪填充（cover）</h3><p>区分两种需求：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 等比缩放，确保完全落在 800x600 内（不变形，可能小于画布）</span>
magick in.png <span class="token parameter variable">-resize</span> 800x600 <span class="token parameter variable">-background</span> white <span class="token parameter variable">-gravity</span> center <span class="token parameter variable">-extent</span> 800x600 out.png

<span class="token comment"># 填充裁剪：先放大铺满再居中裁出 800x600（封面图常用，不留白）</span>
magick in.png <span class="token parameter variable">-resize</span> 800x600^ <span class="token parameter variable">-gravity</span> center <span class="token parameter variable">-extent</span> 800x600 out.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>800x600^</code> 的 <code>^</code> 表示&quot;放大到至少填满&quot;，配合 <code>-extent</code> 裁出精确尺寸，是制作博客封面/轮播图的黄金组合。</p><h3 id="_5-6-配置与委托-delegates" tabindex="-1"><a class="header-anchor" href="#_5-6-配置与委托-delegates" aria-hidden="true">#</a> 5.6 配置与委托（delegates）</h3><ul><li>环境变量： <ul><li><code>MAGICK_HOME</code>：安装根目录。</li><li><code>MAGICK_CONFIGURE_PATH</code>：配置文件搜索路径（可叠加多个，用系统路径分隔符 <code>:</code> 分隔）。</li><li><code>MAGICK_FONT_PATH</code>：字体搜索路径，处理中文水印时把中文字体目录加进来可避免乱码。</li><li><code>MAGICK_THREAD_LIMIT</code>：全局线程上限（0 表示不限制，遵循 CPU）。</li><li><code>MAGICK_MEMORY_LIMIT</code> / <code>MAGICK_MAP_LIMIT</code> / <code>MAGICK_DISK_LIMIT</code>：全局内存/映射/磁盘上限，等效 <code>-limit</code> 的持久化版本。</li></ul></li><li>配置文件：ImageMagick 从编译时预设的路径（Homebrew 下为 <code>/usr/local/etc/ImageMagick-7</code> 或 <code>/opt/homebrew/etc/ImageMagick-7</code>）读取 <code>policy.xml</code>（安全策略）、<code>delegates.xml</code>（委托外部程序）、<code>colors.xml</code>、<code>type.xml</code> 等。查看实际生效路径：</li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick <span class="token parameter variable">-debug</span> configure info: <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span> <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-i</span> config
<span class="token comment"># 或直接打印配置汇总</span>
magick <span class="token parameter variable">-version</span>
magick <span class="token parameter variable">-list</span> configure <span class="token operator">|</span> <span class="token function">grep</span> <span class="token parameter variable">-E</span> <span class="token string">&#39;PREFIX|CONFIGURE|FONT&#39;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><ul><li>查看已支持的编码器与委托工具：</li></ul><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick <span class="token parameter variable">-list</span> <span class="token function">format</span>
magick <span class="token parameter variable">-list</span> delegate
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><blockquote><p><strong>个性化实用配置</strong>：若嫌中文字体每次都要 <code>-font</code> 指定，可新建 <code>type.xml</code> 片段并入搜索路径，或用 <code>-define</code> 设置默认滤镜。更简单的做法：为常用风格写一个 shell 函数（见第七节）。</p></blockquote><h3 id="_5-7-常用-define-与滤镜选项" tabindex="-1"><a class="header-anchor" href="#_5-7-常用-define-与滤镜选项" aria-hidden="true">#</a> 5.7 常用 <code>-define</code> 与滤镜选项</h3><ul><li><code>-define jpeg:size=1000x1000</code>：JPEG <strong>分块解码</strong>，读取大图只解码到所需尺寸再缩放，极大省内存（先缩后解）。</li><li><code>-define filter:support=2.0</code> / <code>-filter Lanczos</code>：控制缩放滤镜质量，<code>Lanczos</code>、<code>LanczosSharp</code>、<code>Catrom</code> 质量较高但慢；<code>Triangle</code>、<code>Box</code> 快但糊。默认 <code>Undefined</code>（自动）。</li><li><code>-strip</code>：删除全部元数据（EXIF、XMP、ICC、注释），压缩利器。</li><li><code>-interlace Plane</code>：写渐进式 JPEG；<code>-interlace None</code> 写基线式。</li><li><code>-sharpen 0x1</code>：缩放后轻度锐化，弥补重采样损失。</li><li><code>-dither FloydSteinberg</code> / <code>-colors 256</code>：量化到 256 色，GIF/缩略图减体积。</li></ul><h3 id="_5-8-颜色空间与通道处理" tabindex="-1"><a class="header-anchor" href="#_5-8-颜色空间与通道处理" aria-hidden="true">#</a> 5.8 颜色空间与通道处理</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 转灰度（灰度图体积约为 RGB 的 1/3）</span>
magick in.png <span class="token parameter variable">-colorspace</span> Gray out.png

<span class="token comment"># 转 sRGB（跨设备统一显示）</span>
magick in.jpg <span class="token parameter variable">-colorspace</span> sRGB out.jpg

<span class="token comment"># 提取/合成单通道（制作透明遮罩）</span>
magick in.png <span class="token parameter variable">-alpha</span> extract mask.png

<span class="token comment"># 反转遮罩（黑白对调）</span>
magick mask.png <span class="token parameter variable">-negate</span> mask_inv.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p><code>-colorspace Gray</code>、<code>-alpha extract</code> 在制作抠图遮罩、缩略图占位图时很常用。</p><h2 id="六、注意事项与常见问题" tabindex="-1"><a class="header-anchor" href="#六、注意事项与常见问题" aria-hidden="true">#</a> 六、注意事项与常见问题</h2><p><strong>1. 7.x 的 <code>convert</code> 已变体</strong></p><p>ImageMagick 7 统一使用 <code>magick</code>，旧的 <code>convert</code> 被重命名为 <code>convert</code>（<code>magick convert</code> 别名）。Homebrew 安装 7.x 后 <code>convert</code> 命令默认仍指向 <code>magick</code> 的兼容入口，但建议新脚本直接用 <code>magick</code>，避免与系统其他软件（如 macOS 自带的 <code>convert</code>）冲突。</p><blockquote><p>排障：若 <code>magick</code> 提示 <code>command not found</code>，先 <code>brew link imagemagick</code> 或在 shell 中 <code>export PATH=&quot;/opt/homebrew/bin:$PATH&quot;</code>（Apple Silicon）。</p></blockquote><p><strong>2. <code>-crop</code> 的 <code>+x+y</code> 是&quot;原点偏移&quot;而非裁剪尺寸</strong></p><p>新手常把 <code>-crop 300x200+100+50</code> 误以为从中心裁剪。实际上 <code>+100+50</code> 表示从左上角偏移 (100,50) 处取 300x200 的区域。要&quot;从中心裁&quot;，可配合 <code>-gravity center</code>：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick big.png <span class="token parameter variable">-gravity</span> center <span class="token parameter variable">-crop</span> 800x600+0+0 +repage out.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><code>+repage</code> 用来重置画布偏移，否则输出会带有虚拟画布偏移导致尺寸异常。</p><p><strong>3. 中文文字水印乱码</strong></p><p>默认字体不含中文字形。叠加中文前先指定中文字体路径，或用系统字体目录：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick photo.png <span class="token parameter variable">-font</span> /System/Library/Fonts/PingFang.ttc <span class="token parameter variable">-pointsize</span> <span class="token number">60</span> <span class="token punctuation">\\</span>
  <span class="token parameter variable">-gravity</span> north <span class="token parameter variable">-annotate</span> +0+20 <span class="token string">&quot;中文水印&quot;</span> out.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div></div></div><p>若 <code>-font</code> 解析失败，先 <code>magick -list font | grep -i pingfang</code> 确认可用字体名。</p><blockquote><p>注意：<code>-annotate</code> 有 <code>+y</code>（基线偏上）与 <code>-y</code>（基线偏下）方向差异；<code>-draw &quot;text ...&quot;</code> 走不同渲染路径，转义规则略异，混用时易踩坑。含中文/空格/特殊字符时建议用 <code>-annotate</code> 并用双引号包裹。</p></blockquote><p><strong>4. 大图处理的内存/磁盘开销</strong></p><p>处理超大图（几百 MB 像素）时 ImageMagick 会占用大量内存，可能 OOM 崩溃。用 <code>-limit</code> 限制资源，或改用流式处理：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick <span class="token parameter variable">-limit</span> memory 1GiB <span class="token parameter variable">-limit</span> map 2GiB <span class="token parameter variable">-resize</span> <span class="token number">50</span>% huge.tif out.png

<span class="token comment"># 超大图优先&quot;先缩后解&quot;（jpeg:size 仅分块解码，大幅省内存）</span>
magick <span class="token parameter variable">-define</span> jpeg:size<span class="token operator">=</span>2000x2000 huge.jpg <span class="token parameter variable">-resize</span> <span class="token number">50</span>% out.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>处理大量文件时优先 <code>mogrify -path</code> 输出到独立目录，便于中途失败时重跑不覆盖原图。</p><blockquote><p>磁盘：当内存/map 用尽时图像落盘到临时文件，注意 <code>TMPDIR</code> 所在分区剩余空间；<code>-limit disk</code> 可设上限。</p></blockquote><p><strong>5. <code>-quality</code> 对 JPEG/PNG/WebP 含义不同</strong></p><ul><li>JPEG：0-100 压缩质量（数值越小体积越小、画质越差）。</li><li>PNG：无损，<code>-quality</code> 数值 0-100 实际表示 <code>zlib</code> 压缩级别（10 为 9 级压缩）与滤波器选择，默认即可。</li><li>WebP：0-100，意义同 JPEG。<br> 做&quot;压缩&quot;时先明确目标格式再设 <code>-quality</code>，否则可能无效。</li></ul><blockquote><p>常见误解：对 PNG 设 <code>-quality 50</code> 不会让画质变差，只是压缩级别；真正减少 PNG 体积常用 <code>-strip</code> + 降位深 + 调色板（<code>-colors 256</code>）。</p></blockquote><p><strong>6. 安全注意：<code>policy.xml</code> 与恶意文件</strong></p><p>ImageMagick 历史上出现过解析恶意 SVG/MVg 文件导致代码执行的漏洞（如 2016 年的 ImageTragick）。生产环境建议收紧 <code>policy.xml</code>，禁用有风险的 delegate（如 <code>MVG</code>、<code>PS</code>、<code>EPHEMERAL</code>、<code>URL</code> 读取）：</p><div class="language-xml line-numbers-mode" data-ext="xml"><pre class="language-xml"><code><span class="token comment">&lt;!-- 放在 &lt;policymap&gt; ... &lt;/policymap&gt; 内部 --&gt;</span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>policy</span> <span class="token attr-name">domain</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>coder<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rights</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>none<span class="token punctuation">&quot;</span></span> <span class="token attr-name">pattern</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>MVG<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>policy</span> <span class="token attr-name">domain</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>coder<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rights</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>none<span class="token punctuation">&quot;</span></span> <span class="token attr-name">pattern</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>URL<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>policy</span> <span class="token attr-name">domain</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>coder<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rights</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>none<span class="token punctuation">&quot;</span></span> <span class="token attr-name">pattern</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>EPHEMERAL<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>policy</span> <span class="token attr-name">domain</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>coder<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rights</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>none<span class="token punctuation">&quot;</span></span> <span class="token attr-name">pattern</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>HTTPS<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>policy</span> <span class="token attr-name">domain</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>coder<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rights</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>none<span class="token punctuation">&quot;</span></span> <span class="token attr-name">pattern</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>HTTP<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>policy</span> <span class="token attr-name">domain</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>delegate<span class="token punctuation">&quot;</span></span> <span class="token attr-name">rights</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>none<span class="token punctuation">&quot;</span></span> <span class="token attr-name">pattern</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>gs<span class="token punctuation">&quot;</span></span> <span class="token punctuation">/&gt;</span></span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>其他建议：</p><ul><li>处理不可信来源的图片前，先 <code>identify</code> 看基本信息；不确定时不要直接 <code>-composite</code> 或触发 delegate。</li><li>限制资源：<code>-limit memory 256MiB -limit map 256MiB -limit disk 1GiB -limit time 30</code>。</li><li>上传接口：先做格式白名单校验（扩展名+<code>magick -format %m</code> 实际探测），禁用 SVG/PDF 直传。</li><li>定期 <code>brew upgrade imagemagick</code> 拉取安全修复。</li></ul><p><strong>7. 脚本中等待/进度输出</strong></p><p>批量任务可用 <code>-monitor</code> 显示进度，用 <code>-quiet</code> 抑制多余日志，配合 <code>set -e</code> 让脚本在出错时立即退出：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code>magick <span class="token parameter variable">-monitor</span> <span class="token parameter variable">-resize</span> <span class="token number">50</span>% <span class="token parameter variable">-path</span> out/ *.jpg
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div></div></div><p><strong>8. 常见报错速查</strong></p><ul><li><code>no decode delegate for this image format</code> / <code>unable to open image</code>: 缺格式 delegate，先 <code>magick -list format</code> 确认，安装对应 Homebrew 包（如 HEIC→<code>brew install libheif</code>，SVG→<code>brew install librsvg</code>）。</li><li><code>cache resources exhausted</code>: 内存/map 超限，用 <code>-limit memory</code>/<code>-limit map</code> 放大或走流式。</li><li><code>unable to read font</code>: <code>-font</code> 路径错误或字体缺失，<code>magick -list font</code> 查可用名。</li><li><code>improper image header</code> / <code>invalid colormap index</code>: 源文件损坏，先 <code>identify</code> 复核。</li><li><code>Segmentation fault</code>：多在旧版本或特定 delegate 上，优先升级/复现最小命令。</li><li>权限类：Homebrew 目录只读时改 <code>-path</code> 输出到用户可写目录，别用 <code>sudo</code> 乱改 <code>/opt/homebrew/etc</code>。</li></ul><h2 id="七、实战-与其它工具搭配与自动化" tabindex="-1"><a class="header-anchor" href="#七、实战-与其它工具搭配与自动化" aria-hidden="true">#</a> 七、实战：与其它工具搭配与自动化</h2><h3 id="_7-1-与-find-xargs-的批量管道" tabindex="-1"><a class="header-anchor" href="#_7-1-与-find-xargs-的批量管道" aria-hidden="true">#</a> 7.1 与 <code>find</code> / <code>xargs</code> 的批量管道</h3><p>海量文件批处理的标准姿势：用 <code>-print0</code>/<code>-0</code> 规避文件名中的空格，<code>xargs -P</code> 并行：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 全部 JPG 压成 WebP（保留比例、最长边 1200）</span>
<span class="token function">find</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.jpg&#39;</span> <span class="token parameter variable">-print0</span> <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-0</span> <span class="token parameter variable">-P</span> <span class="token number">4</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token punctuation">\\</span>
  magick <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token parameter variable">-strip</span> <span class="token parameter variable">-resize</span> <span class="token string">&#39;1200x&gt;&#39;</span> <span class="token parameter variable">-quality</span> <span class="token number">82</span> <span class="token punctuation">{</span><span class="token punctuation">}</span>.webp
<span class="token comment"># &#39;1200x&gt;&#39; 表示&quot;仅当大于 1200 时才缩小&quot;，避免放大糊图</span>

<span class="token comment"># 全部 PNG 统一缩放到宽 400 并改名 _thumb</span>
<span class="token function">find</span> <span class="token builtin class-name">.</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.png&#39;</span> <span class="token parameter variable">-print0</span> <span class="token operator">|</span> <span class="token keyword">while</span> <span class="token assign-left variable"><span class="token environment constant">IFS</span></span><span class="token operator">=</span> <span class="token builtin class-name">read</span> <span class="token parameter variable">-r</span> <span class="token parameter variable">-d</span> <span class="token string">&#39;&#39;</span> f<span class="token punctuation">;</span> <span class="token keyword">do</span>
  magick <span class="token string">&quot;<span class="token variable">$f</span>&quot;</span> <span class="token parameter variable">-resize</span> 400x <span class="token parameter variable">-quality</span> <span class="token number">85</span> <span class="token string">&quot;<span class="token variable">\${f<span class="token operator">%</span>.png}</span>_thumb.png&quot;</span>
<span class="token keyword">done</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-2-makefile-自动化" tabindex="-1"><a class="header-anchor" href="#_7-2-makefile-自动化" aria-hidden="true">#</a> 7.2 Makefile 自动化</h3><p>适合&quot;有输入、有产物&quot;的图片构建流，支持增量构建（源没变就不重跑）：</p><div class="language-makefile line-numbers-mode" data-ext="makefile"><pre class="language-makefile"><code><span class="token comment"># Makefile —— 站点图片优化</span>
SRC <span class="token operator">:=</span> <span class="token variable">$</span><span class="token punctuation">(</span><span class="token function">wildcard</span> img-src/*.png<span class="token punctuation">)</span>
OUT <span class="token operator">:=</span> <span class="token variable">$</span><span class="token punctuation">(</span><span class="token function">patsubst</span> img-src/%.png,img-out/%.webp,<span class="token variable">$</span><span class="token punctuation">(</span>SRC<span class="token punctuation">)</span><span class="token punctuation">)</span>

<span class="token target symbol">all</span><span class="token punctuation">:</span> <span class="token variable">$</span><span class="token punctuation">(</span>OUT<span class="token punctuation">)</span>

<span class="token target symbol">img-out/%.webp</span><span class="token punctuation">:</span> img-src/%.png <span class="token operator">|</span> img-out
	magick <span class="token variable">$&lt;</span> -strip -resize <span class="token string">&#39;1200x&gt;&#39;</span> -quality 80 <span class="token variable">$@</span>

<span class="token target symbol">img-out</span><span class="token punctuation">:</span>
	mkdir -p <span class="token variable">$@</span>

<span class="token comment"># 把目录下所有 png 生成一张缩略图拼图</span>
<span class="token target symbol">sprite.png</span><span class="token punctuation">:</span> <span class="token variable">$</span><span class="token punctuation">(</span>SRC<span class="token punctuation">)</span>
	montage <span class="token variable">$^</span> -tile 5x -geometry 200x200+8+8 -background none <span class="token variable">$@</span>

<span class="token target symbol">clean</span><span class="token punctuation">:</span>
	rm -rf img-out sprite.png
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>用法：<code>make</code> 全量、<code>make img-out/a.webp</code> 单张、<code>make clean</code> 清理。<code>$&lt;</code>=首个依赖、<code>$@</code>=目标、<code>$^</code>=全部依赖。</p><h3 id="_7-3-ci-集成-github-actions" tabindex="-1"><a class="header-anchor" href="#_7-3-ci-集成-github-actions" aria-hidden="true">#</a> 7.3 CI 集成（GitHub Actions）</h3><p>在 CI 里批量压缩图片并提交回仓库（需配套 <code>actions/checkout</code> 与 <code>stefanzweifel/git-auto-commit-action</code> 类步骤）：</p><div class="language-yaml line-numbers-mode" data-ext="yml"><pre class="language-yaml"><code><span class="token comment"># .github/workflows/optimize-images.yml</span>
<span class="token key atrule">name</span><span class="token punctuation">:</span> Optimize images
<span class="token key atrule">on</span><span class="token punctuation">:</span>
  <span class="token key atrule">push</span><span class="token punctuation">:</span>
    <span class="token key atrule">paths</span><span class="token punctuation">:</span> <span class="token punctuation">[</span><span class="token string">&#39;public/images/**&#39;</span><span class="token punctuation">]</span>
<span class="token key atrule">jobs</span><span class="token punctuation">:</span>
  <span class="token key atrule">optimize</span><span class="token punctuation">:</span>
    <span class="token key atrule">runs-on</span><span class="token punctuation">:</span> ubuntu<span class="token punctuation">-</span>latest
    <span class="token key atrule">steps</span><span class="token punctuation">:</span>
      <span class="token punctuation">-</span> <span class="token key atrule">uses</span><span class="token punctuation">:</span> actions/checkout@v4
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Install ImageMagick
        <span class="token key atrule">run</span><span class="token punctuation">:</span> sudo apt<span class="token punctuation">-</span>get update <span class="token important">&amp;&amp;</span> sudo apt<span class="token punctuation">-</span>get install <span class="token punctuation">-</span>y imagemagick
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Optimize WebP
        <span class="token key atrule">run</span><span class="token punctuation">:</span> <span class="token punctuation">|</span><span class="token scalar string">
          find public/images -name &#39;*.png&#39; -o -name &#39;*.jpg&#39; | while read f; do
            magick &quot;$f&quot; -strip -resize &#39;1600x&gt;&#39; -quality 80 &quot;\${f%.*}.webp&quot;
          done</span>
      <span class="token punctuation">-</span> <span class="token key atrule">name</span><span class="token punctuation">:</span> Commit changes
        <span class="token key atrule">uses</span><span class="token punctuation">:</span> stefanzweifel/git<span class="token punctuation">-</span>auto<span class="token punctuation">-</span>commit<span class="token punctuation">-</span>action@v5
        <span class="token key atrule">with</span><span class="token punctuation">:</span>
          <span class="token key atrule">commit_message</span><span class="token punctuation">:</span> <span class="token string">&quot;chore: optimize images&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>要点：CI 环境常是 Debian 系（无 Homebrew），用 <code>apt-get</code> 装；可加 <code>gh-actions-cache</code> 缓存 delegate 安装以提速；输出到独立目录再 git add，避免污染源图。</p><h3 id="_7-4-与其他工具的管道" tabindex="-1"><a class="header-anchor" href="#_7-4-与其他工具的管道" aria-hidden="true">#</a> 7.4 与其他工具的管道</h3><p>ImageMagick 走标准输入输出，可接入各种工具链：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 截图 → 处理 → 直接粘贴到剪贴板（macOS）</span>
screencapture <span class="token parameter variable">-x</span> <span class="token parameter variable">-t</span> png - <span class="token operator">|</span> magick - <span class="token parameter variable">-resize</span> <span class="token number">50</span>% - <span class="token operator">|</span> pbcopy

<span class="token comment"># 生成缩略图并上传到对象存储（配合 curl）</span>
magick in.png <span class="token parameter variable">-resize</span> 400x thumb.png <span class="token operator">&amp;&amp;</span> <span class="token function">curl</span> <span class="token parameter variable">-F</span> <span class="token string">&quot;file=@thumb.png&quot;</span> https://oss.example.com/upload

<span class="token comment"># 用变量记录尺寸再做条件分支（配合 shell）</span>
<span class="token assign-left variable">w</span><span class="token operator">=</span><span class="token variable"><span class="token variable">$(</span>magick in.png <span class="token parameter variable">-format</span> <span class="token string">&quot;%w&quot;</span> info:<span class="token variable">)</span></span>
<span class="token punctuation">[</span> <span class="token string">&quot;<span class="token variable">$w</span>&quot;</span> <span class="token parameter variable">-gt</span> <span class="token number">1200</span> <span class="token punctuation">]</span> <span class="token operator">&amp;&amp;</span> magick in.png <span class="token parameter variable">-resize</span> 1200x out.png

<span class="token comment"># 对比两张图（配合 compare 输出差异图/度量）</span>
compare <span class="token parameter variable">-metric</span> RMSE before.png after.png diff.png <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
<span class="token comment"># 配合 jq 解析 JSON 型像素差度量</span>
compare <span class="token parameter variable">-metric</span> PSNR before.png after.png null: <span class="token operator"><span class="token file-descriptor important">2</span>&gt;</span><span class="token file-descriptor important">&amp;1</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-5-生产级脚本模板" tabindex="-1"><a class="header-anchor" href="#_7-5-生产级脚本模板" aria-hidden="true">#</a> 7.5 生产级脚本模板</h3><p>一个带参数、幂等、可重入的批量处理脚本骨架：</p><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token shebang important">#!/usr/bin/env bash</span>
<span class="token comment"># imgflow —— 站点图片批量处理入口</span>
<span class="token builtin class-name">set</span> <span class="token parameter variable">-euo</span> pipefail

<span class="token assign-left variable">SRC_DIR</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">\${1<span class="token operator">:-</span>.<span class="token operator">/</span>img-src}</span>&quot;</span>   <span class="token comment"># 源目录</span>
<span class="token assign-left variable">OUT_DIR</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">\${2<span class="token operator">:-</span>.<span class="token operator">/</span>img-out}</span>&quot;</span>   <span class="token comment"># 输出目录</span>
<span class="token assign-left variable">QUALITY</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">\${QUALITY<span class="token operator">:-</span>80}</span>&quot;</span>    <span class="token comment"># 可由环境变量覆盖</span>
<span class="token assign-left variable">MAX_W</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">\${MAX_W<span class="token operator">:-</span>1600}</span>&quot;</span>      <span class="token comment"># 最长边上限</span>
<span class="token assign-left variable">THREADS</span><span class="token operator">=</span><span class="token string">&quot;<span class="token variable">\${THREADS<span class="token operator">:-</span>$(nproc)}</span>&quot;</span>

<span class="token function">mkdir</span> <span class="token parameter variable">-p</span> <span class="token string">&quot;<span class="token variable">$OUT_DIR</span>&quot;</span>
<span class="token builtin class-name">export</span> <span class="token assign-left variable">MAGICK_THREAD_LIMIT</span><span class="token operator">=</span><span class="token number">1</span>   <span class="token comment"># 让 xargs -P 进程级并行接管</span>

<span class="token function">find</span> <span class="token string">&quot;<span class="token variable">$SRC_DIR</span>&quot;</span> <span class="token punctuation">\\</span><span class="token punctuation">(</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.jpg&#39;</span> <span class="token parameter variable">-o</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.png&#39;</span> <span class="token parameter variable">-o</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.webp&#39;</span> <span class="token punctuation">\\</span><span class="token punctuation">)</span> <span class="token parameter variable">-print0</span> <span class="token punctuation">\\</span>
  <span class="token operator">|</span> <span class="token function">xargs</span> <span class="token parameter variable">-0</span> <span class="token parameter variable">-P</span> <span class="token string">&quot;<span class="token variable">$THREADS</span>&quot;</span> -I<span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token function">bash</span> <span class="token parameter variable">-c</span> <span class="token string">&#39;
      f=&quot;$1&quot;
      out=&quot;$2/$(basename &quot;\${f%.*}.webp&quot;)&quot;
      # 幂等：输出已存在且新于输入则跳过
      if [[ -f &quot;$out&quot; &amp;&amp; &quot;$out&quot; -nt &quot;$f&quot; ]]; then exit 0; fi
      magick &quot;$f&quot; -strip -resize &quot;\${3}x&gt;&quot; -quality &quot;$4&quot; &quot;$out&quot;
    &#39;</span> _ <span class="token punctuation">{</span><span class="token punctuation">}</span> <span class="token string">&quot;<span class="token variable">$OUT_DIR</span>&quot;</span> <span class="token string">&quot;<span class="token variable">$MAX_W</span>&quot;</span> <span class="token string">&quot;<span class="token variable">$QUALITY</span>&quot;</span>

<span class="token comment"># 汇总统计</span>
<span class="token builtin class-name">echo</span> <span class="token string">&quot;--- 输出统计 ---&quot;</span>
<span class="token function">find</span> <span class="token string">&quot;<span class="token variable">$OUT_DIR</span>&quot;</span> <span class="token parameter variable">-name</span> <span class="token string">&#39;*.webp&#39;</span> <span class="token operator">|</span> <span class="token function">xargs</span> identify <span class="token parameter variable">-format</span> <span class="token string">&quot;%f %wx%h %b<span class="token entity" title="\\n">\\n</span>&quot;</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>特性：环境变量可配、<code>nproc</code> 自适应并行、<code>-nt</code> 实现增量跳过、错误时 <code>set -e</code> 立即退出。</p><h3 id="_7-6-用-shell-函数固化常用风格" tabindex="-1"><a class="header-anchor" href="#_7-6-用-shell-函数固化常用风格" aria-hidden="true">#</a> 7.6 用 shell 函数固化常用风格</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 放入 ~/.bashrc / ~/.zshrc</span>
<span class="token comment"># 封面图：填满 1200x630（OG 图规格）</span>
<span class="token function-name function">og_cover</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> magick <span class="token string">&quot;<span class="token variable">$1</span>&quot;</span> <span class="token parameter variable">-strip</span> <span class="token parameter variable">-resize</span> <span class="token string">&#39;1200x630^&#39;</span> <span class="token parameter variable">-gravity</span> center <span class="token parameter variable">-extent</span> 1200x630 <span class="token parameter variable">-quality</span> <span class="token number">82</span> <span class="token string">&quot;<span class="token variable">\${1<span class="token operator">%</span>.*}</span>-og.jpg&quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment"># 缩略图：最长边 400</span>
<span class="token function-name function">thumb</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> magick <span class="token string">&quot;<span class="token variable">$1</span>&quot;</span> <span class="token parameter variable">-strip</span> <span class="token parameter variable">-resize</span> <span class="token string">&#39;400x&gt;&#39;</span> <span class="token parameter variable">-quality</span> <span class="token number">80</span> <span class="token string">&quot;<span class="token variable">\${1<span class="token operator">%</span>.*}</span>-thumb.webp&quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>
<span class="token comment"># 统一压缩成 webp</span>
<span class="token function-name function">towebp</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token punctuation">{</span> magick <span class="token string">&quot;<span class="token variable">$1</span>&quot;</span> <span class="token parameter variable">-strip</span> <span class="token parameter variable">-resize</span> <span class="token string">&quot;<span class="token variable">\${2<span class="token operator">:-</span>1600}</span>x&gt;&quot;</span> <span class="token parameter variable">-quality</span> <span class="token string">&quot;<span class="token variable">\${3<span class="token operator">:-</span>80}</span>&quot;</span> <span class="token string">&quot;<span class="token variable">\${1<span class="token operator">%</span>.*}</span>.webp&quot;</span><span class="token punctuation">;</span> <span class="token punctuation">}</span>

<span class="token comment"># 使用</span>
og_cover banner.png
thumb photo.jpg
towebp big.png <span class="token number">1200</span> <span class="token number">75</span>
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_7-7-批量加编号-时间戳与-exif-写入" tabindex="-1"><a class="header-anchor" href="#_7-7-批量加编号-时间戳与-exif-写入" aria-hidden="true">#</a> 7.7 批量加编号/时间戳与 EXIF 写入</h3><div class="language-bash line-numbers-mode" data-ext="sh"><pre class="language-bash"><code><span class="token comment"># 批量加时间戳水印</span>
<span class="token keyword">for</span> <span class="token for-or-select variable">f</span> <span class="token keyword">in</span> *.jpg<span class="token punctuation">;</span> <span class="token keyword">do</span>
  magick <span class="token string">&quot;<span class="token variable">$f</span>&quot;</span> <span class="token parameter variable">-gravity</span> southeast <span class="token parameter variable">-pointsize</span> <span class="token number">30</span> <span class="token punctuation">\\</span>
    <span class="token parameter variable">-fill</span> <span class="token string">&quot;rgba(255,255,255,0.7)&quot;</span> <span class="token punctuation">\\</span>
    <span class="token parameter variable">-annotate</span> +15+15 <span class="token string">&quot;<span class="token variable"><span class="token variable">$(</span><span class="token function">date</span> +%Y-%m-%d<span class="token variable">)</span></span>&quot;</span> <span class="token string">&quot;stamped_<span class="token variable">$f</span>&quot;</span>
<span class="token keyword">done</span>

<span class="token comment"># 写 EXIF（作者/版权/描述）</span>
magick in.jpg <span class="token parameter variable">-set</span> exif:Artist <span class="token string">&quot;BeauXbot&quot;</span> <span class="token parameter variable">-set</span> exif:Copyright <span class="token string">&quot;© 2024&quot;</span> out.jpg

<span class="token comment"># 只读 EXIF 部分字段（配合 jq 解析）</span>
identify <span class="token parameter variable">-format</span> <span class="token string">&quot;%[EXIF:DateTimeOriginal]<span class="token entity" title="\\n">\\n</span>&quot;</span> photo.jpg
</code></pre><div class="line-numbers" aria-hidden="true"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><hr>`,110),i=[p];function o(c,l){return n(),s("div",null,i)}const u=a(t,[["render",o],["__file","imagemagick.html.vue"]]);export{u as default};
